import sqlite3

import streamlit as st

import config
import database
import friends
import models
import ui_components


def _your_profile(connection, user_id):
    """Show a copyable code, explicit sharing permission and validated friend-code input."""
    profile = database.get_user_profile(connection, user_id)
    st.subheader('You')
    st.text(profile.display_name)
    st.code(f'Add me on WeekWise – my friend code is {profile.friend_code}.', language=None)
    saved = friends.get_sharing_opt_in(connection, user_id)
    sharing = st.toggle('Share my WeekWise plans with friends', value=saved, key='ww_share_plans')
    st.caption('Sharing is off by default. Only WeekWise activities are shared, '
               'never private calendar entries. Sending an invitation shares that activity.')
    if sharing != saved:
        friends.set_sharing_opt_in(connection, user_id, sharing)
        st.rerun()
    code = st.text_input('Friend code', key='ww_friend_code_input')
    if st.button('Add a friend', key='ww_add_friend'):
        try:
            friend_id = friends.add_friend(connection, user_id, code)
            st.session_state['ww_friend_added'] = database.get_user_profile(
                connection, friend_id).display_name
            st.rerun()
        except ValueError as error:
            st.error(str(error))
    if 'ww_friend_added' in st.session_state:
        st.success(st.session_state.pop('ww_friend_added') + ' added as a friend.')
    with st.expander('Demo friend codes'):
        for name, demo_code in zip(config.SYNTHETIC_NAMES[config.SHOWCASE_PRE_ADDED:],
                                    config.SHOWCASE_CODES[config.SHOWCASE_PRE_ADDED:]):
            st.text(name + ' (synthetic demo user)')
            st.code(demo_code, language=None)


def _friends_and_plans(connection, user_id, now):
    """List public friend names and show upcoming plans only when their owners opted in."""
    st.subheader('Friends')
    people = friends.get_friends_df(connection, user_id)
    plans = friends.get_friend_plans_df(connection, user_id, now)
    if people.empty:
        st.info('No friends yet. Add a friend with their code.')
    for person in people.reset_index().to_dict('records'):
        with st.container(border=True):
            st.text(person['display_name'] + (' (demo)' if person['is_synthetic'] else ''))
            if not person['sharing_opt_in']:
                st.caption('Not sharing plans.')
                continue
            selected = plans.loc[plans['friend_id'] == person['id']]
            if selected.empty:
                st.caption('No upcoming shared plans.')
            for row in selected.to_dict('records'):
                st.text(row['title'])
                st.caption(row['start_time'] + ' – ' + row['end_time'])
                ui_components.direction_badge(row['direction_key'])
                if st.button('Details', key=f'ww_friend_plan_{person["id"]}_{row["event_id"]}'):
                    st.session_state['ww_open_event_id'] = row['event_id']


def _received_invitations(connection, received, now):
    """Show all incoming invitations, including those that do not fit a calendar gap."""
    st.subheader('Invitations received')
    if received.empty:
        st.caption('No invitations received yet.')
    for row in received.reset_index().to_dict('records'):
        with st.container(border=True):
            st.text(row['sender_name'] + ' invited you')
            st.text(row['title'])
            st.caption(row['start_time'] + ' – ' + row['end_time'])
            ui_components.direction_badge(row['direction_key'])
            if row['is_simulated'] and row['status'] == 'pending':
                st.caption('Demo invitation')
            if row['status'] == 'pending':
                event = models.event_from_row(database.get_event_row(connection, row['event_id']))
                st.caption(ui_components.calendar_fit_message(connection, event, now))
            ui_components.render_invitation_response(connection, row, now)
            if st.button('Details', key=f'ww_received_details_{row["id"]}'):
                st.session_state['ww_open_event_id'] = row['event_id']


def _sent_invitations(sent):
    """Display saved recipient outcomes and distinguish simulated answers from real responses."""
    st.subheader('Invitations sent')
    if sent.empty:
        st.caption('Confirm a future activity, then open Details to invite friends.')
    for row in sent.to_dict('records'):
        with st.container(border=True):
            st.text(row['title'] + ' · ' + row['recipient_name'])
            st.caption(row['start_time'])
            suffix = ' (simulated)' if row['is_simulated'] else ''
            st.caption(row['status'].capitalize() + suffix)


def render_friends(connection, now=None):
    """Render the two-column friends page without reading or revealing friends' calendars."""
    now = config.local_now(now)
    user_id = database.get_current_user_id(connection)
    st.title('Friends')
    st.write('Plan activities together. Friend codes and invitations work inside this local app.')
    # Course: L04 – two columns compose small controls; all queries and decisions live in logic.
    left, right = st.columns([1, 2])
    with left:
        _your_profile(connection, user_id)
    with right:
        _friends_and_plans(connection, user_id, now)
        invitations = friends.get_invitations(connection, user_id)
        _received_invitations(connection, invitations['received'], now)
        _sent_invitations(invitations['sent'])
    ui_components.render_sidebar_status()


try:
    render_friends(ui_components.cached_connection())
except (OSError, ValueError, KeyError, sqlite3.Error) as error:
    st.error(str(error) if isinstance(error, ValueError) else
             'Could not load friends. Please refresh the page and try again.')
